+    @Test void signedZeroWithoutRateOrCarriedFlowRaisesNoNewTransition() throws Exception {
+        var pipe = new PassiveNetwork.Pipe(3, 0, 1,
+                new PipeResistance.Geometry(100, 0.05, 0.000045, 0));
+        var graph = new PassiveNetwork(List.of(
+                new PassiveNetwork.Reservoir(1, 0, water(160000).withSolids(particles(100))),
+                new PassiveNetwork.Reservoir(2, 0, water(150000))), List.of(pipe));
+        var states = graph.reservoirs().stream().map(PassiveNetwork.Reservoir::state).toList();
+        var events = new SolidEventIntegrator(model, new PassiveIntervalSolver(model));
+        var failed = SolidEventIntegrator.class.getDeclaredMethod(
+                "failed", PassiveNetwork.class, List.class, double[].class, boolean[].class);
+        failed.setAccessible(true);
+
+        // A failed rate solve with no carried flow supplies no still classification. Exactly zero
+        // has no donor and cannot create transport; its floating-point sign must not invent one.
+        assertNull(failed.invoke(events, graph, states, new double[]{-0.0}, (boolean[]) null));
+        assertNull(failed.invoke(events, graph, states, new double[]{0.0}, (boolean[]) null));
+
+        var moving = (SolidEventIntegrator.Transition) failed.invoke(
+                events, graph, states, new double[]{Double.MIN_VALUE}, (boolean[]) null);
+        assertNotNull(moving, "A real, nonzero slow carrier still deposits");
+        assertEquals(com.wormzjl.icheme.science.fluid.transport.SolidMobility.Reason.DEPOSITION,
+                moving.reason());
+    }
